    /**
     * Tests getting all Regulations.
     *
     * @return    Collection
     */
    public List<Regulation> testGetAll() throws Throwable {
    LOGGER.info( "RegulationTest:testGetAll() - Retrieving Collection of Regulations:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Regulation : " );
    List<Regulation> collection  = null;

    try {
        // call the static get method on the RegulationService
        collection = service.getAllRegulation();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Regulation currEntity  = null;
            Iterator<Regulation> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getRegulationId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

